CREATE OR REPLACE FUNCTION wms.check_reversal_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'wms', 'pg_temp'
AS $function$
DECLARE tx inventory_transaction; original inventory_transaction;
BEGIN
  IF TG_TABLE_NAME='inventory_transaction' THEN
    SELECT * INTO tx FROM inventory_transaction WHERE id=NEW.id;
  ELSE
    SELECT * INTO tx FROM inventory_transaction WHERE id=NEW.transaction_id;
  END IF;
  IF tx.operation<>'REVERSE' AND tx.reverses_transaction_id IS NULL THEN
    IF TG_TABLE_NAME='stock_move' THEN
      IF NEW.reverses_move_id IS NOT NULL THEN
        RAISE EXCEPTION 'Inverse move needs reversal transaction' USING ERRCODE='23514';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO original FROM inventory_transaction WHERE id=tx.reverses_transaction_id;
  IF tx.operation<>'REVERSE' OR original.id IS NULL OR original.operation='REVERSE'
     OR original.reverses_transaction_id IS NOT NULL OR tx.business_date<original.business_date
     OR NOT EXISTS (SELECT 1 FROM document d JOIN reversal_document r ON r.document_id=d.id
       WHERE d.id=tx.document_id AND d.kind='REVERSAL' AND r.source_transaction_id=original.id)
     OR NOT EXISTS (SELECT 1 FROM stock_move WHERE transaction_id=original.id)
     OR (SELECT count(*) FROM stock_move WHERE transaction_id=tx.id)<>
        (SELECT count(*) FROM stock_move WHERE transaction_id=original.id)
     OR EXISTS (
       SELECT 1 FROM stock_move m LEFT JOIN stock_move s ON s.id=m.reverses_move_id
       LEFT JOIN reversal_line r ON r.document_line_id=m.line_id
       JOIN document_line l ON l.id=m.line_id
       WHERE m.transaction_id=tx.id AND (s.id IS NULL OR s.transaction_id<>original.id
         OR l.document_id<>tx.document_id OR l.source_line_id IS DISTINCT FROM s.line_id
         OR r.source_move_id IS DISTINCT FROM s.id
         OR (m.stock_item_id,m.source_location_id,m.destination_location_id,m.quantity_base,m.base_uom_id)
            IS DISTINCT FROM (s.stock_item_id,s.destination_location_id,s.source_location_id,s.quantity_base,s.base_uom_id))
     ) THEN
    RAISE EXCEPTION 'Reversal must be the complete exact inverse of one original transaction' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_approval_decision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' OR OLD.status<>'PENDING' OR
     (NEW.request_id,NEW.step_no,NEW.required_role_id,NEW.alternative_role_id)
     IS DISTINCT FROM (OLD.request_id,OLD.step_no,OLD.required_role_id,OLD.alternative_role_id) THEN
    RAISE EXCEPTION 'Approval decision/roles are immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.status IN ('APPROVED','REJECTED') AND
     (NEW.decided_by IS NULL OR NEW.decided_at IS NULL OR length(trim(COALESCE(NEW.comment,'')))=0) THEN
    RAISE EXCEPTION 'Decision needs actor, time and reason' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_custom_field_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'wms', 'pg_temp'
AS $function$
DECLARE expected_type text; actual_type text; current_status text;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Custom field bindings cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW.product_id IS DISTINCT FROM OLD.product_id
      OR NEW.document_id IS DISTINCT FROM OLD.document_id) THEN
    RAISE EXCEPTION 'Custom field target is immutable' USING ERRCODE='23514';
  END IF;
  SELECT s.entity_type INTO expected_type FROM custom_field_revision r
    JOIN custom_field_schema s ON s.id=r.schema_id WHERE r.id=NEW.revision_id;
  IF NEW.document_id IS NOT NULL THEN
    SELECT kind,status INTO actual_type,current_status FROM document WHERE id=NEW.document_id FOR UPDATE;
    IF current_status NOT IN ('DRAFT','REJECTED') THEN
      RAISE EXCEPTION 'Custom fields require a draft document' USING ERRCODE='23514';
    END IF;
  ELSE
    actual_type := 'PRODUCT';
    PERFORM 1 FROM product WHERE id=NEW.product_id FOR UPDATE;
  END IF;
  IF actual_type IS DISTINCT FROM expected_type THEN
    RAISE EXCEPTION 'Custom field scope mismatch' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_custom_field_definition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.revision_id IS NOT NULL OR (TG_OP='UPDATE' AND NEW.revision_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Managed definitions are append-only' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_document_line_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE owner_kind text; agreement_owner uuid;
BEGIN
  IF TG_OP='UPDATE' AND (NEW.owner_id,NEW.consignment_id) IS NOT DISTINCT FROM (OLD.owner_id,OLD.consignment_id) THEN
    RETURN NEW;
  END IF;
  IF TG_OP='UPDATE' AND (EXISTS(SELECT 1 FROM wms.stock_move WHERE line_id=OLD.id)
                        OR EXISTS(SELECT 1 FROM wms.reservation WHERE line_id=OLD.id)) THEN
    RAISE EXCEPTION 'Posted/reserved line ownership is immutable' USING ERRCODE='23514';
  END IF;
  SELECT kind INTO owner_kind FROM wms.stock_owner WHERE id=NEW.owner_id AND is_active;
  IF owner_kind IS NULL OR owner_kind='UNCLASSIFIED'
     OR (owner_kind='CONSIGNOR') IS DISTINCT FROM (NEW.consignment_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Select an explicit valid owner/agreement' USING ERRCODE='23514';
  END IF;
  IF NEW.consignment_id IS NOT NULL THEN
    SELECT owner_id INTO agreement_owner FROM wms.consignment_agreement WHERE id=NEW.consignment_id;
    IF agreement_owner IS DISTINCT FROM NEW.owner_id THEN
      RAISE EXCEPTION 'Agreement owner differs from document line' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_move_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE item wms.stock_item; line wms.document_line; owner_kind text;
  agreement wms.consignment_agreement; operation_kind text; business_day date;
  destination_warehouse uuid; source_location wms.location; destination_location wms.location; document_kind text;
BEGIN
  SELECT * INTO item FROM wms.stock_item WHERE id=NEW.stock_item_id;
  SELECT * INTO line FROM wms.document_line WHERE id=NEW.line_id;
  IF item.id IS NULL OR line.id IS NULL THEN RETURN NEW; END IF;
  IF (item.owner_id,item.consignment_id) IS DISTINCT FROM (line.owner_id,line.consignment_id) THEN
    RAISE EXCEPTION 'Move and document owner differ' USING ERRCODE='23514';
  END IF;
  SELECT kind INTO owner_kind FROM wms.stock_owner WHERE id=item.owner_id;
  IF owner_kind='UNCLASSIFIED' THEN RAISE EXCEPTION 'Legacy ownership needs reconciliation' USING ERRCODE='23514'; END IF;
  IF owner_kind='CONSIGNOR' THEN
    IF NEW.reverses_move_id IS NOT NULL THEN
      RAISE EXCEPTION 'Consignment reversal policy is not enabled' USING ERRCODE='23514';
    END IF;
    SELECT * INTO agreement FROM wms.consignment_agreement WHERE id=item.consignment_id FOR SHARE;
    SELECT operation,business_date INTO operation_kind,business_day FROM wms.inventory_transaction WHERE id=NEW.transaction_id;
    SELECT warehouse_id INTO destination_warehouse FROM wms.location WHERE id=NEW.destination_location_id;
    IF operation_kind='MOVE' THEN
      SELECT * INTO source_location FROM wms.location WHERE id=NEW.source_location_id;
      SELECT * INTO destination_location FROM wms.location WHERE id=NEW.destination_location_id;
      SELECT d.kind INTO document_kind FROM wms.inventory_transaction t
        JOIN wms.document d ON d.id=t.document_id WHERE t.id=NEW.transaction_id;
      IF document_kind IS DISTINCT FROM 'INTERNAL_MOVE'
         OR source_location.warehouse_id IS DISTINCT FROM agreement.warehouse_id
         OR destination_location.warehouse_id IS DISTINCT FROM agreement.warehouse_id
         OR source_location.kind NOT IN ('STORAGE','RECEIVING','QUARANTINE')
         OR destination_location.kind NOT IN ('STORAGE','RECEIVING','QUARANTINE') THEN
        RAISE EXCEPTION 'Only same-owner physical internal movement is enabled' USING ERRCODE='23514';
      END IF;
    ELSIF operation_kind='ADJUST' THEN
      IF NOT EXISTS (
        SELECT 1 FROM wms.count_session s
        JOIN wms.document d ON d.id=s.adjustment_document_id AND d.kind='ADJUSTMENT' AND d.status='APPROVED'
        JOIN wms.inventory_transaction t ON t.document_id=d.id AND t.id=NEW.transaction_id
        JOIN wms.count_line cl ON cl.session_id=s.id AND cl.stock_item_id=NEW.stock_item_id
        JOIN wms.location loc ON loc.id=cl.location_id AND loc.warehouse_id=s.warehouse_id
        JOIN wms.count_location_lock lk ON lk.session_id=s.id AND lk.location_id=loc.id AND lk.released_at IS NULL
        WHERE s.status='SUBMITTED' AND s.warehouse_id=agreement.warehouse_id AND line.document_id=d.id
          AND loc.kind IN ('STORAGE','RECEIVING','QUARANTINE','SHIPPING')
          AND NEW.quantity_base=abs(cl.approved_quantity-cl.snapshot_quantity)
          AND ((cl.approved_quantity<cl.snapshot_quantity AND NEW.source_location_id=cl.location_id
                AND NEW.destination_location_id='00000000-0000-4130-8000-000000000020')
            OR (cl.approved_quantity>cl.snapshot_quantity AND NEW.destination_location_id=cl.location_id
                AND NEW.source_location_id='00000000-0000-4130-8000-000000000020'))
          AND 2=(SELECT count(*) FROM wms.count_decision cd WHERE cd.decision='APPROVE'
            AND cd.submission_id=(SELECT cs.id FROM wms.count_submission cs WHERE cs.session_id=s.id ORDER BY cs.session_version DESC LIMIT 1))
      ) THEN
        RAISE EXCEPTION 'Consignment adjustment requires approved frozen count evidence' USING ERRCODE='23514';
      END IF;
      destination_warehouse := agreement.warehouse_id;
    ELSIF operation_kind NOT IN ('RECEIVE','OPEN') THEN
      RAISE EXCEPTION 'Consignment outbound/transfer/reversal policy is not enabled' USING ERRCODE='23514';
    END IF;
    IF NOT agreement.is_active OR destination_warehouse IS DISTINCT FROM agreement.warehouse_id
       OR business_day NOT BETWEEN agreement.valid_from AND agreement.valid_until THEN
      RAISE EXCEPTION 'Agreement is inactive, out of date or outside warehouse' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_owner_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Owner identity is permanent' USING ERRCODE='23514'; END IF;
  IF (NEW.kind,NEW.partner_id) IS DISTINCT FROM (OLD.kind,OLD.partner_id)
     OR OLD.kind IN ('COMPANY','UNCLASSIFIED') THEN
    RAISE EXCEPTION 'Owner identity is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_reservation_owner()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE item wms.stock_item; line wms.document_line; owner_kind text;
BEGIN
  SELECT * INTO item FROM wms.stock_item WHERE id=NEW.stock_item_id;
  SELECT * INTO line FROM wms.document_line WHERE id=NEW.line_id;
  IF item.id IS NULL OR line.id IS NULL THEN RETURN NEW; END IF;
  IF (item.owner_id,item.consignment_id) IS DISTINCT FROM (line.owner_id,line.consignment_id) THEN
    RAISE EXCEPTION 'Reservation owner differs from order line' USING ERRCODE='23514';
  END IF;
  SELECT kind INTO owner_kind FROM wms.stock_owner WHERE id=item.owner_id;
  IF TG_OP='INSERT' AND owner_kind<>'COMPANY' THEN
    RAISE EXCEPTION 'Reservation policy for consigned/unclassified stock is not enabled' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_serial_owner_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE serial_key uuid;
BEGIN
  SELECT serial_id INTO serial_key FROM wms.stock_item WHERE id=NEW.stock_item_id;
  IF serial_key IS NOT NULL THEN
    PERFORM id FROM wms.serial WHERE id=serial_key FOR UPDATE;
    IF NEW.on_hand NOT IN (0,1) OR (NEW.on_hand=1 AND EXISTS (
      SELECT 1 FROM wms.stock_balance b JOIN wms.stock_item i ON i.id=b.stock_item_id
      WHERE i.serial_id=serial_key AND b.id<>NEW.id AND b.on_hand>0
    )) THEN
      RAISE EXCEPTION 'Serial already has a physical position, regardless of owner' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_stock_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE owner_kind text; agreement_owner uuid; tracking_kind text; related_product uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'Stock identity is immutable; ownership conversion needs a dedicated workflow' USING ERRCODE='23514';
  END IF;
  SELECT kind INTO owner_kind FROM wms.stock_owner WHERE id=NEW.owner_id AND is_active;
  IF owner_kind IS NULL THEN RAISE EXCEPTION 'Unknown or inactive owner' USING ERRCODE='23514'; END IF;
  IF owner_kind='UNCLASSIFIED' THEN
    RAISE EXCEPTION 'Select an explicit owner for new stock' USING ERRCODE='23514';
  END IF;
  IF (owner_kind='CONSIGNOR') IS DISTINCT FROM (NEW.consignment_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Consigned stock requires an agreement' USING ERRCODE='23514';
  END IF;
  IF NEW.consignment_id IS NOT NULL THEN
    SELECT owner_id INTO agreement_owner FROM wms.consignment_agreement WHERE id=NEW.consignment_id;
    IF agreement_owner IS DISTINCT FROM NEW.owner_id THEN
      RAISE EXCEPTION 'Agreement belongs to another owner' USING ERRCODE='23514';
    END IF;
  END IF;
  SELECT tracking INTO tracking_kind FROM wms.product WHERE id=NEW.product_id;
  IF tracking_kind='NONE' AND (NEW.lot_id IS NOT NULL OR NEW.serial_id IS NOT NULL)
     OR tracking_kind='LOT' AND (NEW.lot_id IS NULL OR NEW.serial_id IS NOT NULL)
     OR tracking_kind='SERIAL' AND (NEW.serial_id IS NULL OR NEW.lot_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Tracking does not match SKU' USING ERRCODE='23514';
  END IF;
  IF NEW.lot_id IS NOT NULL THEN
    SELECT product_id INTO related_product FROM wms.lot WHERE id=NEW.lot_id;
    IF related_product IS DISTINCT FROM NEW.product_id THEN RAISE EXCEPTION 'Lot SKU mismatch' USING ERRCODE='23514'; END IF;
  END IF;
  IF NEW.serial_id IS NOT NULL THEN
    SELECT product_id INTO related_product FROM wms.serial WHERE id=NEW.serial_id FOR UPDATE;
    IF related_product IS DISTINCT FROM NEW.product_id THEN RAISE EXCEPTION 'Serial SKU mismatch' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.guard_transfer_move()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d wms.document; t wms.inventory_transaction; plan wms.transfer_line; dest wms.location;
BEGIN
 SELECT * INTO t FROM wms.inventory_transaction WHERE id=NEW.transaction_id;
 SELECT * INTO d FROM wms.document WHERE id=t.document_id;
 IF d.kind='TRANSFER' THEN
   SELECT * INTO plan FROM wms.transfer_line WHERE document_line_id=NEW.line_id;
   SELECT * INTO dest FROM wms.location WHERE id=NEW.destination_location_id;
   IF plan.document_line_id IS NULL OR plan.stock_item_id IS DISTINCT FROM NEW.stock_item_id
      OR NEW.reverses_move_id IS NOT NULL
      OR NOT EXISTS(SELECT 1 FROM wms.document_line WHERE id=NEW.line_id AND document_id=d.id)
      OR NOT EXISTS(SELECT 1 FROM wms.location WHERE id=d.transit_location_id AND kind='TRANSIT' AND warehouse_id IS NULL)
      OR ((t.operation='DISPATCH' AND NEW.source_location_id=plan.source_location_id AND NEW.destination_location_id=d.transit_location_id)
           OR (t.operation='ARRIVE' AND NEW.source_location_id=d.transit_location_id AND dest.warehouse_id=d.destination_warehouse_id AND dest.kind IN ('RECEIVING','QUARANTINE'))) IS NOT TRUE THEN
     RAISE EXCEPTION 'Transfer movement does not match approved route' USING ERRCODE='23514';
   END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION wms.protect_conversion_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Conversion history is immutable';
  END IF;
  IF (NEW.id, NEW.product_id, NEW.uom_id, NEW.factor, NEW.revision)
     IS DISTINCT FROM (OLD.id, OLD.product_id, OLD.uom_id, OLD.factor, OLD.revision) THEN
    RAISE EXCEPTION 'Create a new conversion revision';
  END IF;
  RETURN NEW;
END $function$
